"use client";

import { useEffect, useRef, useState } from "react";
import { EqualizerPanel } from "@/components/audio-ui/devices/equalizer/panel";
import { useDemoSource } from "@/hooks/use-demo-source";
import { useMasterBus } from "@/hooks/use-master-bus";
import { usePlaySwitch } from "@/hooks/use-play-switch";
import { useSpectrum } from "@/hooks/use-spectrum";
import { renderDemoSource } from "@/lib/demo-sound";
import {
  type EqualizerState,
  equalizerDevice,
} from "@/components/audio-ui/devices/equalizer/device";
import {
  createEqualizerEngine,
  type EqualizerEngine,
} from "@/components/audio-ui/devices/equalizer/engine";
import { webAudio } from "@/lib/web-audio";

const FFT_SIZE = 4096;
const ANALYSER_SMOOTHING = 0.8;
const MASTER_VOLUME = 0.7;
const MIN_HZ = 20;
const MAX_HZ = 20_000;
/** A shape worth looking at: some weight, a dip in the low mids, some air. */
const START = { highDb: 5, lowDb: 3, lowMidDb: -4 };

/**
 * An equalizer you can plug in: its state, a panel that draws it and an engine
 * that plays it, each its own file and none knowing the others. A loop
 * plays through it while its session's play switch is on, and the spectrum
 * behind the curve is what comes out.
 */
export function BlockEqualizer() {
  const [state, setState] = useState<EqualizerState>(
    () => equalizerDevice.apply(equalizerDevice.defaults(), START).state
  );
  const { playing } = usePlaySwitch();
  const [analyser, setAnalyser] = useState<AnalyserNode | null>(null);
  const master = useMasterBus(MASTER_VOLUME);
  const engine = useRef<EqualizerEngine | null>(null);
  const stateRef = useRef(state);
  stateRef.current = state;
  const spectrum = useSpectrum(analyser, { maxHz: MAX_HZ, minHz: MIN_HZ });

  const name = useDemoSource("groove");
  useEffect(() => {
    const ctx = webAudio.getContext();
    if (!(playing && ctx && master)) {
      return;
    }
    ctx.resume();
    let cancelled = false;
    let stop = () => undefined;
    renderDemoSource(name, ctx.sampleRate).then((buffer) => {
      if (cancelled) {
        return;
      }
      const source = ctx.createBufferSource();
      source.buffer = buffer;
      source.loop = true;
      const eq = createEqualizerEngine(ctx, stateRef.current);
      const tap = ctx.createAnalyser();
      tap.fftSize = FFT_SIZE;
      tap.smoothingTimeConstant = ANALYSER_SMOOTHING;
      source.connect(eq.input);
      eq.output.connect(tap);
      eq.output.connect(master);
      engine.current = eq;
      source.start();
      setAnalyser(tap);
      stop = () => {
        source.stop();
        source.disconnect();
        tap.disconnect();
        eq.dispose();
        engine.current = null;
        setAnalyser(null);
      };
    });
    return () => {
      cancelled = true;
      stop();
    };
  }, [master, name, playing]);

  // The engine follows the state, whoever changed it: a handle, a knob or a call.
  useEffect(() => {
    engine.current?.update(state);
  }, [state]);

  return (
    <div className="rounded-xl h-full w-full min-w-0">
      <EqualizerPanel
        onValueChange={setState}
        spectrum={spectrum}
        value={state}
      />
    </div>
  );
}
